create or replace function public.signal_submit_intercept(p_room_id uuid,p_intercept text) returns jsonb language plpgsql security definer set search_path=public,auth as $$ begin if p_intercept not in('left','right') or not exists(select 1 from public.room_players p join public.rooms r on r.id=p.room_id where p.room_id=p_room_id and p.user_id=auth.uid() and p.team<>r.active_team) then raise exception 'opposing team required';end if;update public.rounds set intercept=p_intercept where id=(select id from public.rounds where room_id=p_room_id order by created_at desc limit 1);update public.rooms set game_state=jsonb_build_object('phase','reveal_pending','intercept',p_intercept) where id=p_room_id;return jsonb_build_object('ok',true);end;$$;

create or replace function public.signal_reveal_round(p_room_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare r public.rounds; room public.rooms; d int; a int:=0; b int:=0; begin select * into room from public.rooms where id=p_room_id and host_id=auth.uid() for update;if not found then raise exception 'host required';end if;if room.status<>'intercept' then raise exception 'round is not ready to reveal';end if;select * into r from public.rounds where room_id=p_room_id order by created_at desc limit 1 for update;if r.needle is null or r.intercept is null then raise exception 'round incomplete';end if;d:=abs(r.needle-r.target);a:=case when d<=5 then 4 when d<=12 then 3 when d<=20 then 2 else 0 end;b:=case when a<>4 and ((r.target<r.needle and r.intercept='left') or (r.target>r.needle and r.intercept='right')) then 1 else 0 end;update public.rounds set active_score=a,intercept_score=b where id=r.id;update public.rooms set amber_score=amber_score+case when active_team='amber' then a else b end,violet_score=violet_score+case when active_team='violet' then a else b end,status='reveal',game_state=jsonb_build_object('phase','reveal','target',r.target,'needle',r.needle,'activeScore',a,'interceptScore',b) where id=p_room_id returning * into room;return to_jsonb(room);end;$$;

grant execute on function public.signal_submit_intercept(uuid,text),public.signal_reveal_round(uuid) to authenticated;
